INSERT INTO public.templates (leaf_id, template_version, body_md, source_file, must_count, should_count, last_loaded_at, last_loaded_by) VALUES ('req:8.2:applicable_assessment_scope', 1, '---
leaf_id: req:8.2:applicable_assessment_scope
