INSERT INTO public.templates (leaf_id, template_version, body_md, source_file, must_count, should_count, last_loaded_at, last_loaded_by) VALUES ('req:B.8.2.2:purpose_limitation_procedure', 1, '---
leaf_id: req:B.8.2.2:purpose_limitation_procedure
