INSERT INTO public.templates (leaf_id, template_version, body_md, source_file, must_count, should_count, last_loaded_at, last_loaded_by) VALUES ('req:A.5.4:communication_record', 1, '---
leaf_id: req:A.5.4:communication_record
control_ref: A.5.4
standard_id: ISO27001:2022
evidence_type: communication_record
trigger_type: universal
template_version: 1
