INSERT INTO public.templates (leaf_id, template_version, body_md, source_file, must_count, should_count, last_loaded_at, last_loaded_by) VALUES ('req:A.8.3:information_access_restriction_procedure', 1, '---
leaf_id: req:A.8.3:information_access_restriction_procedure
