INSERT INTO public.templates (leaf_id, template_version, body_md, source_file, must_count, should_count, last_loaded_at, last_loaded_by) VALUES ('req:Art.24:privacy_programme_charter', 1, '---
leaf_id: req:Art.24:privacy_programme_charter
