INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('incident_response', 'req:A.5.24:incident_response_procedure', 'primary_procedure', 1, 'The plan itself. Defines roles, escalation paths, RACI, and
decision authorities. Prerequisite to executing anything else.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('incident_response', 'req:A.5.24:incident_response_team_register', 'supporting_prerequisite', 2, 'Named on-call responders + contact details. Fresh (updated on
HR changes) — stale roster is a common finding.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('incident_response', 'req:A.5.24:framework_exercise_record', 'review_record', 3, 'Evidence of drills / tabletop exercises. Auditors look for
at least annual; A.5.24 wants demonstrable readiness.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('incident_response', 'req:A.5.25:event_assessment_procedure', 'primary_procedure', 4, 'The triage decision criteria — what qualifies as an incident
vs. an event. Load-bearing for the 72h Art.33 clock.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('incident_response', 'req:A.5.25:event_triage_log', 'log', 5, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('incident_response', 'req:A.5.26:incident_response_procedure', 'primary_procedure', 6, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('incident_response', 'req:A.5.26:incident_register', 'primary_register', 7, 'One row per incident with severity, timeline, root cause,
containment actions, closure decision.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('incident_response', 'req:A.5.26:incident_closure_record', 'evidence', 8, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('incident_response', 'req:Art.33:notification_procedure', 'supporting_cross_framework', 9, 'The 72h decision workflow for when an incident is a personal
data breach requiring SA notification. Coordinated with A.5.26
closure.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('incident_response', 'req:Art.33:breach_notification', 'form', 10, 'The notification letter template (SA + affected subjects).');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('risk_assessment_treatment', 'req:6.1.2:risk_methodology_scope', 'primary_procedure', 1, 'The documented methodology — criteria for likelihood, impact,
risk acceptance thresholds. Written once, referenced everywhere.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('risk_assessment_treatment', 'req:6.1.2:risk_assessment', 'primary_procedure', 2, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('risk_assessment_treatment', 'req:6.1.2:risk_register', 'primary_register', 3, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('risk_assessment_treatment', 'req:6.1.3:treatment_methodology_scope', 'primary_procedure', 4, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('risk_assessment_treatment', 'req:6.1.3:risk_treatment_plan', 'primary_register', 5, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('risk_assessment_treatment', 'req:6.1.3:statement_of_applicability', 'primary_register', 6, 'The Statement of Applicability — a first-look audit
artefact. Every Annex A control listed with in-scope decision
+ justification. Certifiers reject SoAs where every control
is just "applicable" with no reasoning.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('risk_assessment_treatment', 'req:8.2:assessment_trigger_procedure', 'primary_procedure', 7, 'When to re-run risk assessment: significant change, incident,
new asset, control failure. Prevents the "annual freeze"
failure mode where risk assessments happen once a year only.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('risk_assessment_treatment', 'req:8.2:operational_risk_assessment_record', 'log', 8, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('risk_assessment_treatment', 'req:8.3:treatment_execution_procedure', 'primary_procedure', 9, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('risk_assessment_treatment', 'req:8.3:operational_risk_treatment_record', 'log', 10, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('breach_notification', 'req:Art.33:notification_procedure', 'primary_procedure', 1, 'The decision workflow: is this a personal data breach?
Notification required? Which SA(s)? Timeline gates.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('breach_notification', 'req:Art.33:breach_notification', 'form', 2, 'The SA notification letter template with Art.33(3) required
content (nature, categories, likely consequences, measures).');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('breach_notification', 'req:Art.33:applicable_scope', 'supporting_prerequisite', 3, 'Which SAs are competent for your establishments — critical
for the "notify without undue delay" 72h clock.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('breach_notification', 'req:Art.33:breach_program_review', 'review_record', 4, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('breach_notification', 'req:A.5.26:incident_register', 'supporting_iso_mirror', 5, 'The same register captures both incidents and breaches;
breach notification is triggered from this record when
Art.33 applies.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('breach_notification', 'req:A.6.8:event_reporting_procedure', 'supporting_prerequisite', 0, 'Staff-side event reporting — if events aren''t reported
internally, the 72h clock starts too late.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('breach_notification', 'req:A.7.3.7:third_party_notification_procedure', 'supporting_iso_mirror', 6, 'ISO 27701 controller extension. Third-party notification
procedure — shared discipline with breach notification.
Downstream processors + joint controllers need to be told
about both breaches AND rectification/erasure changes.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('consent_and_lawful_basis', 'req:Art.6:lawful_basis_determination_procedure', 'primary_procedure', 1, 'Lawfulness of processing — the anchor obligation. Every
processing activity gets mapped to one of six lawful bases.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('consent_and_lawful_basis', 'req:Art.6:lawful_basis_register', 'primary_register', 2, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('consent_and_lawful_basis', 'req:Art.7:consent_management_procedure', 'primary_procedure', 3, 'Conditions for consent (when consent is the chosen basis).
Includes Art.7(3) withdrawal + Art.7(1) documentation.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('consent_and_lawful_basis', 'req:Art.7:consent_register', 'primary_register', 4, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('consent_and_lawful_basis', 'req:Art.9:special_category_authorisation_procedure', 'supporting_prerequisite', 5, 'Special categories require both an Art.6 basis AND an Art.9
exception. This procedure documents which Art.9(2) exception
applies per relevant processing operation.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('consent_and_lawful_basis', 'req:Art.8:child_consent_procedure', 'supporting_prerequisite', 6, 'Children''s data — Art.8 age-verification + parental consent
requirements when information society services are offered
directly to children.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('consent_and_lawful_basis', 'req:A.7.2.1:purpose_procedure', 'supporting_iso_mirror', 7, 'ISO 27701 controller extension. Identify and document purpose
— PIMS discipline for recording WHY each processing operation
exists. Prerequisite to lawful-basis mapping.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('consent_and_lawful_basis', 'req:A.7.2.2:lawful_basis_procedure', 'supporting_iso_mirror', 8, 'ISO 27701 controller extension. Operationalizes GDPR Art.6
in the PIMS.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('consent_and_lawful_basis', 'req:A.7.2.3:consent_process_procedure', 'supporting_iso_mirror', 9, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('consent_and_lawful_basis', 'req:A.7.2.4:consent_capture_procedure', 'supporting_iso_mirror', 10, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('consent_and_lawful_basis', 'req:A.7.2.4:consent_record_register', 'supporting_iso_mirror', 11, 'ISO 27701 controller extension. The audit-defensible consent
register required by Art.7(1) "burden of proof."');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('consent_and_lawful_basis', 'req:A.5.34:privacy_and_pii_protection_policy', 'supporting_iso_mirror', 0, 'ISO 27001 program layer. The PII protection policy declares
the tenant''s commitment to lawful-basis discipline that
this bundle operationalizes.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('data_transfers_disclosures', 'req:Art.44:transfer_principle_procedure', 'primary_procedure', 1, 'General principle — every transfer must ensure the same
level of protection as in the EU. Umbrella obligation.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('data_transfers_disclosures', 'req:Art.46:appropriate_safeguards_procedure', 'primary_procedure', 2, 'Appropriate safeguards route — SCCs, BCRs, codes of conduct.
Post-Schrems II supplementary measures required per EDPB
Recommendations 01/2020.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('data_transfers_disclosures', 'req:Art.45:adequacy_procedure', 'supporting_prerequisite', 3, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('data_transfers_disclosures', 'req:Art.49:derogations_procedure', 'supporting_prerequisite', 4, 'Derogations — strict-construction path per EDPB 02/2018.
Only usable when Art.45/46 routes aren''t available.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('data_transfers_disclosures', 'req:A.7.5.1:transfer_basis_procedure', 'primary_procedure', 5, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('data_transfers_disclosures', 'req:A.7.5.2:destinations_procedure', 'primary_procedure', 6, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('data_transfers_disclosures', 'req:A.7.5.2:transfer_destinations_register', 'primary_register', 7, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('data_transfers_disclosures', 'req:A.7.5.3:transfer_records_procedure', 'supporting_iso_mirror', 8, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('data_transfers_disclosures', 'req:A.7.5.3:transfer_event_log', 'log', 9, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('data_transfers_disclosures', 'req:A.7.5.4:disclosure_records_procedure', 'supporting_iso_mirror', 10, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('data_transfers_disclosures', 'req:B.8.5.4:notification_procedure', 'supporting_iso_mirror', 11, 'ISO 27701 processor extension. Notification of PII disclosure
requests — the "we got a subpoena" workflow. Timing + customer
notification obligations are load-bearing.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('data_transfers_disclosures', 'req:B.8.5.5:disclosure_decision_procedure', 'supporting_iso_mirror', 12, 'ISO 27701 processor extension. Legally-binding disclosures —
the decision-making + logging discipline for compelled
disclosures.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('data_transfers_disclosures', 'req:B.8.5.6:subcontractor_disclosure_procedure', 'supporting_iso_mirror', 13, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('data_transfers_disclosures', 'req:A.5.14:information_transfer_policy', 'supporting_iso_mirror', 0, 'ISO 27001 program layer. Information transfer policy — the
overarching non-PII-specific policy that this bundle refines.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dpia_workflow', 'req:Art.35:dpia_procedure', 'primary_procedure', 2, 'The DPIA methodology — aligned with WP29 wp248 rev.01 (still
the definitive DPIA reference).');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dpia_workflow', 'req:Art.35:applicable_scope', 'primary_procedure', 1, 'Screening criteria — which processing operations trigger a
mandatory DPIA. Load-bearing for the whole workflow.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dpia_workflow', 'req:Art.35:dpia_register', 'primary_register', 3, 'One row per DPIA — subject processing operation, decision,
residual risk level, next review date.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dpia_workflow', 'req:Art.35:dpia_program_review', 'review_record', 4, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dpia_workflow', 'req:Art.25:dpbd_procedure', 'supporting_prerequisite', 0, 'Data Protection by Design procedure. DPIAs assess processing
operations against this design discipline — DPbD failures are
often what a DPIA surfaces.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dpia_workflow', 'req:A.7.2.5:pia_procedure', 'supporting_iso_mirror', 5, 'ISO 27701 extension. Privacy Impact Assessment procedure —
the PIMS discipline that integrates DPIA methodology into
the ISMS. Auditors expect PIA + DPIA integrated when both
27701 and GDPR are in scope.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dpia_workflow', 'req:A.7.2.5:pia_register', 'supporting_iso_mirror', 6, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dpia_workflow', 'req:8.2:assessment_trigger_procedure', 'supporting_iso_mirror', 7, 'ISO 27001 program layer. DPIA triggers plug into the same
operational-risk-assessment discipline. Shared discipline
reduces double-work.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dpia_workflow', 'req:Art.22:automated_decision_procedure', 'supporting_prerequisite', 8, 'GDPR obligation. Art.22 automated decision-making + profiling.
Triggers a mandatory DPIA under Art.35.3.a and requires
dedicated data-subject-rights handling (right to human
intervention).');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dpia_workflow', 'req:A.7.3.10:automated_decision_obligations_procedure', 'supporting_iso_mirror', 9, 'ISO 27701 controller extension. The PIMS discipline for
automated decisions — how the controller documents the
logic + provides meaningful information about it.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dsr_management', 'req:Art.15:dsar_handling_procedure', 'primary_procedure', 2, 'The core "how staff process a DSAR" — receive, verify identity,
scope, retrieve, redact, respond within 1 month.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dsr_management', 'req:Art.15:dsar_register', 'primary_register', 3, 'One row per DSR received. Auditor first-look artefact —
completeness + response-timeline compliance visible at a glance.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dsr_management', 'req:Art.15:dsar_response', 'form', 4, 'The letter template used to reply to the subject. Ensures
Art.15 required content (confirmation, categories, retention,
third-country transfers, safeguards, rights, source, automated
decisions) is preserved.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dsr_management', 'req:Art.15:dsar_process_review', 'review_record', 5, 'Periodic (quarterly / annual) review of DSR handling —
volume, response-time compliance, missed-deadline root causes.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dsr_management', 'req:Art.16:rectification_procedure', 'supporting_cross_framework', 6, 'Rectification requests use a subset of the same lifecycle but
have different data-integrity implications (downstream
propagation to processors under Art.19).');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dsr_management', 'req:Art.17:erasure_procedure', 'supporting_cross_framework', 7, 'Erasure is the highest-friction DSR type — coordination with
backups, processors, and Art.17(3) exceptions is needed.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dsr_management', 'req:A.5.34:privacy_and_pii_protection_policy', 'supporting_iso_mirror', 0, 'ISO 27001 program layer. Underlying PII protection policy so
DSR retrieval can locate the right data (prerequisite for a
complete DSR search).');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dsr_management', 'req:A.7.3.6:acr_procedure', 'supporting_iso_mirror', 8, 'ISO 27701 extension. Access-Correction-Restrict-Erasure
integrated procedure — the PIMS mirror of GDPR Art.15-17.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dsr_management', 'req:A.7.3.8:copy_provision_procedure', 'supporting_iso_mirror', 9, 'ISO 27701 extension. Providing a copy of PII processed —
operationalizes GDPR Art.15(3) via the PIMS discipline.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dsr_management', 'req:A.7.3.5:objection_procedure', 'supporting_iso_mirror', 10, 'ISO 27701 extension. Right to object handling — mirrors
GDPR Art.21 in the PIMS layer.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dsr_management', 'req:A.7.3.9:request_handling_procedure', 'supporting_iso_mirror', 11, 'ISO 27701 extension. Master request handling procedure —
the umbrella that integrates access, correction, erasure,
objection, portability, and restriction handling into one
operational workflow. Auditor-defensible integration layer.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('dsr_management', 'req:A.7.3.9:master_request_register', 'primary_register', 12, 'Unified DSR register spanning all rights types — often
preferred by auditors over per-rights-type registers.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('pii_lifecycle', 'req:A.7.4.1:collection_limitation_procedure', 'primary_procedure', 1, 'Limit collection — the "least PII" discipline at ingest.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('pii_lifecycle', 'req:A.7.4.2:processing_limitation_procedure', 'primary_procedure', 2, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('pii_lifecycle', 'req:A.7.4.3:accuracy_procedure', 'supporting_iso_mirror', 3, 'Accuracy + quality — Art.5.1(d) accuracy principle
operationalized.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('pii_lifecycle', 'req:A.7.4.4:minimization_procedure', 'primary_procedure', 4, 'Minimization objectives — Art.5.1(c) data minimization
operationalized with measurable targets.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('pii_lifecycle', 'req:A.7.4.5:end_of_processing_procedure', 'primary_procedure', 5, 'De-identification + deletion at end of processing.
Auditor-critical — evidence that data actually leaves when
processing purpose ends.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('pii_lifecycle', 'req:A.7.4.6:temp_files_procedure', 'supporting_iso_mirror', 6, 'Temporary files — filesystem journals, roll-back files,
application temp files. Frequently overlooked class of PII
persistence.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('pii_lifecycle', 'req:A.7.4.7:retention_procedure', 'primary_procedure', 7, 'Retention procedure + schedule register. Foundational — the
other lifecycle controls execute against this schedule.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('pii_lifecycle', 'req:A.7.4.7:retention_schedule_register', 'primary_register', 8, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('pii_lifecycle', 'req:A.7.4.8:disposal_procedure', 'primary_procedure', 9, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('pii_lifecycle', 'req:A.7.4.9:transmission_controls_procedure', 'supporting_iso_mirror', 10, 'PII transmission controls — encryption + segmentation in
motion. Companion to A.8.24 use of cryptography.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('pii_lifecycle', 'req:A.8.10:information_deletion_procedure', 'supporting_iso_mirror', 0, 'ISO 27001 program layer. Information deletion procedure —
the general (non-PII-specific) deletion discipline that
A.7.4.5 + A.7.4.8 refine for PII.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('pii_lifecycle', 'req:A.5.13:information_labelling_procedure', 'supporting_iso_mirror', 11, 'ISO 27001 program layer. Labelling drives lifecycle
automation — retention rules operate on labels.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('privacy_notice_transparency', 'req:Art.12:transparency_procedure', 'primary_procedure', 1, 'Transparency — Art.12 requires information provided under
Art.13-14 to be concise, transparent, intelligible, in
clear + plain language.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('privacy_notice_transparency', 'req:Art.13:privacy_notice', 'primary_procedure', 2, 'Direct-collection privacy notice — mandated content per
Art.13(1) + Art.13(2).');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('privacy_notice_transparency', 'req:Art.14:privacy_notice', 'primary_procedure', 3, 'Indirect-collection privacy notice — Art.14 applies when
PII is received from a source other than the data subject.
Different timing constraints from Art.13.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('privacy_notice_transparency', 'req:Art.13:publication_record', 'log', 4, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('privacy_notice_transparency', 'req:A.7.3.1:obligations_procedure', 'supporting_iso_mirror', 5, 'ISO 27701 controller extension. Determining and fulfilling
obligations to PII principals — umbrella procedure that the
privacy notice and other rights mechanisms sit inside.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('privacy_notice_transparency', 'req:A.7.3.2:notice_content_procedure', 'supporting_iso_mirror', 6, 'ISO 27701 controller extension. Determining information for
PII principals — the WHAT of the privacy notice.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('privacy_notice_transparency', 'req:A.7.3.3:notice_delivery_procedure', 'supporting_iso_mirror', 7, 'ISO 27701 controller extension. Providing information to PII
principals — the HOW / WHEN of notice delivery.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('privacy_notice_transparency', 'req:A.7.3.3:notice_delivery_log', 'log', 8, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('privacy_notice_transparency', 'req:A.7.3.4:consent_withdrawal_procedure', 'supporting_iso_mirror', 9, 'ISO 27701 controller extension. Providing mechanism to modify
or withdraw consent — operationalizes Art.7(3).');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('privacy_notice_transparency', 'req:A.7.3.4:withdrawal_event_register', 'primary_register', 10, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('privacy_notice_transparency', 'req:A.5.14:information_transfer_policy', 'supporting_iso_mirror', 0, 'ISO 27001 program layer. Information transfer policy —
broader discipline that privacy notice delivery fits within.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('processor_operations', 'req:Art.28:data_processing_agreement', 'primary_procedure', 1, 'GDPR obligation. The customer contract — Art.28(3) content
requirements viewed from the processor side.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('processor_operations', 'req:Art.28:processor_register', 'primary_register', 2, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('processor_operations', 'req:B.8.2.1:customer_agreement_procedure', 'primary_procedure', 3, 'ISO 27701 processor extension. The customer agreement
lifecycle from the processor''s operational side.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('processor_operations', 'req:B.8.2.2:purpose_limitation_procedure', 'primary_procedure', 4, 'Processor may only process on documented instructions —
cannot add purposes beyond what the customer instructed.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('processor_operations', 'req:B.8.2.4:infringing_instruction_procedure', 'primary_procedure', 5, 'Processor must refuse (or flag) instructions that infringe
applicable law. B.8.2.4 is the mechanism.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('processor_operations', 'req:B.8.2.5:customer_information_procedure', 'primary_procedure', 6, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('processor_operations', 'req:B.8.2.5:customer_audit_register', 'primary_register', 7, 'Records of customer audits + processor''s audit-support
responses.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('processor_operations', 'req:B.8.2.6:ropa_maintenance_procedure', 'primary_procedure', 8, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('processor_operations', 'req:B.8.2.6:processor_ropa_register', 'primary_register', 9, 'Processor RoPA — mandated by Art.30(2). Distinct from the
controller RoPA.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('processor_operations', 'req:B.8.3.1:principal_obligations_support_procedure', 'supporting_iso_mirror', 10, 'Processor must assist the customer controller in fulfilling
the controller''s Art.15-22 obligations. Load-bearing for
cloud SaaS.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('processor_operations', 'req:B.8.4.1:temp_files_procedure', 'supporting_iso_mirror', 11, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('processor_operations', 'req:B.8.4.2:return_transfer_disposal_procedure', 'primary_procedure', 12, 'End-of-service data return, transfer, or disposal. The
exit ramp — often overlooked until a customer terminates.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('processor_operations', 'req:B.8.4.3:transmission_procedure', 'supporting_iso_mirror', 13, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('processor_operations', 'req:A.5.34:privacy_and_pii_protection_policy', 'supporting_iso_mirror', 0, 'ISO 27001 program layer. The tenant''s PII protection policy
declares processor-mode commitments to customer controllers.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('records_of_processing', 'req:Art.30:records_of_processing', 'primary_register', 2, 'The RoPA itself. Auditor first-look artefact. Common
failures: missing Art.30(1)(f) retention periods, missing
Art.30(1)(g) technical + organisational measures reference,
stale (last updated > 12 months ago).');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('records_of_processing', 'req:Art.30:ropa_maintenance_procedure', 'primary_procedure', 1, 'When to update the RoPA — new processing operation, purpose
change, transfer route change, retention-period change,
third-party engagement.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('records_of_processing', 'req:Art.30:data_flow_inventory', 'supporting_prerequisite', 0, 'Where does each PII category actually live — systems,
backups, third parties. Prerequisite for a complete RoPA;
auditors triangulate the RoPA against this inventory.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('records_of_processing', 'req:Art.30:ropa_annual_review', 'review_record', 3, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('records_of_processing', 'req:A.5.34:privacy_and_pii_protection_policy', 'supporting_iso_mirror', 4, 'ISO 27001 program layer. The PII protection policy defines
the RoPA''s scope + governance. Auditors look for the RoPA
being coherent with this policy.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('records_of_processing', 'req:A.7.5.1:transfer_basis_procedure', 'supporting_iso_mirror', 5, 'ISO 27701 controller extension. Basis for PII transfer
between jurisdictions — mandated Art.30(1)(e) content:
transfers to third countries + safeguards.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('records_of_processing', 'req:A.7.5.3:transfer_records_procedure', 'supporting_iso_mirror', 6, 'ISO 27701 controller extension. Records of PII transfer —
the operational record that backs Art.30(1)(e) claims.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('records_of_processing', 'req:B.8.2.6:processor_ropa_register', 'supporting_iso_mirror', 7, 'ISO 27701 processor extension. Processor-side RoPA covering
Art.30(2). When the tenant is a processor as well as a
controller, both registers exist alongside.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('records_of_processing', 'req:A.7.2.8:pii_processing_ropa', 'supporting_iso_mirror', 8, 'ISO 27701 controller extension. Records related to processing
PII — the PIMS operational anchor for maintaining the RoPA.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('records_of_processing', 'req:A.7.2.8:ropa_maintenance_procedure', 'supporting_iso_mirror', 9, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('supplier_onboarding', 'req:A.5.19:supplier_risk_procedure', 'primary_procedure', 1, 'Pre-onboarding due diligence: what security assessment does
each supplier category get before contract signature.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('supplier_onboarding', 'req:A.5.19:supplier_register', 'primary_register', 2, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('supplier_onboarding', 'req:A.5.20:supplier_agreement_security_template', 'form', 3, 'Master security addendum bolted onto every supplier
agreement. Reduces per-supplier drafting to filling blanks.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('supplier_onboarding', 'req:A.5.20:coverage_register', 'log', 4, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('supplier_onboarding', 'req:Art.28:data_processing_agreement', 'form', 5, 'DPA template with Art.28(3) mandatory content — subject
matter, duration, nature/purpose, types of PII, obligations.
EDPB 07/2020 has the authoritative content list.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('supplier_onboarding', 'req:Art.28:processor_register', 'primary_register', 6, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('supplier_onboarding', 'req:A.5.22:supplier_review_record', 'review_record', 7, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('supplier_onboarding', 'req:A.5.22:review_schedule_register', 'log', 8, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('supplier_onboarding', 'req:A.5.21:ict_supply_chain_procedure', 'supporting_prerequisite', 9, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('supplier_onboarding', 'req:A.5.19:offboarding_record', 'evidence', 10, NULL);
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('supplier_onboarding', 'req:B.8.2.1:customer_agreement_procedure', 'supporting_iso_mirror', 11, 'ISO 27701 processor extension. PIMS discipline for the
customer agreement that operationalizes GDPR Art.28. When
the tenant is a processor for downstream customers, this
is the primary contractual gate.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('supplier_onboarding', 'req:B.8.2.5:customer_information_procedure', 'supporting_iso_mirror', 12, 'ISO 27701 processor extension. Customer information + audit
support — how the processor supports the customer''s own
compliance obligations under Art.28.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('supplier_onboarding', 'req:B.8.2.6:processor_ropa_register', 'supporting_iso_mirror', 13, 'ISO 27701 processor extension. Processor RoPA per GDPR
Art.30(2). Distinct from the controller RoPA — mirrors
records_of_processing bundle from the processor side.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('supplier_onboarding', 'req:A.7.2.6:processor_contract_procedure', 'supporting_iso_mirror', 14, 'ISO 27701 controller extension. Contracts with PII
processors — the controller-side operational discipline
that produces the DPA required by GDPR Art.28.');
INSERT INTO public.topic_leaves (topic_slug, leaf_id, role, workflow_order, role_note) VALUES ('supplier_onboarding', 'req:A.7.2.7:joint_controller_procedure', 'supporting_iso_mirror', 15, 'ISO 27701 controller extension. Joint PII controller
arrangements — where responsibility is shared, GDPR Art.26
requires a transparent arrangement documented under this
procedure.');

-- retention_policies: cross-tenant defaults (tenant_id IS NULL) --
INSERT INTO public.retention_policies VALUES ('34614983-6b67-4163-a75d-7fcf1cef3faa', NULL, 'compliance', NULL, '7', '0', NULL, 'false', 'ISO 27001 A.5.33, GDPR Art.5(1)(e)', 'Compliance records retained 7 years, manual review before purge', '2026-04-29 15:20:51.415792+00');
INSERT INTO public.retention_policies VALUES ('0f957a12-7fba-4b7d-b3a6-4e655f33cd8b', NULL, 'compliance', 'posture_controls', '7', '0', NULL, 'false', 'ISO 27001 A.5.33', 'Posture history required for audit trail', '2026-04-29 15:20:51.415792+00');
INSERT INTO public.retention_policies VALUES ('1af379c1-320e-4329-a499-c0e5cc690182', NULL, 'compliance', 'isms_audits', '7', '0', NULL, 'false', 'ISO 27001 A.5.33', 'Audit records required for surveillance audits', '2026-04-29 15:20:51.415792+00');
INSERT INTO public.retention_policies VALUES ('6c0ae18f-762d-49f3-9e39-6ddbc7719946', NULL, 'compliance', 'incidents', '7', '0', '5', 'false', 'ISO 27001 A.5.26, GDPR Art.33', 'Anonymise personal data after 5 years, retain incident record for 7', '2026-04-29 15:20:51.415792+00');
INSERT INTO public.retention_policies VALUES ('ed1c7a2d-2b48-4405-9d7a-330929132c30', NULL, 'compliance', 'document_findings', '7', '0', NULL, 'false', 'ISO 27001 A.5.33', 'Evidence of document evaluation retained', '2026-04-29 15:20:51.415792+00');
INSERT INTO public.retention_policies VALUES ('f03550a5-2b50-4330-b026-3bfd703bc252', NULL, 'operational', NULL, '5', '0', '3', 'true', 'ISO 27001 A.5.33, GDPR Art.5(1)(e)', 'Operational records 5 years, PII anonymised after 3', '2026-04-29 15:20:51.415792+00');
INSERT INTO public.retention_policies VALUES ('64f4966a-d276-476b-a0e5-285a5d2e0c86', NULL, 'operational', 'risks', '5', '0', '3', 'true', 'ISO 27001 A.5.33', 'Risk register retained 5 years', '2026-04-29 15:20:51.415792+00');
INSERT INTO public.retention_policies VALUES ('f1620c21-f464-47ae-b7b0-42555b86fd96', NULL, 'operational', 'vendors', '5', '0', '3', 'true', 'ISO 27001 A.5.33, GDPR Art.28', 'Processor agreements 5 years, contact data anonymised at 3', '2026-04-29 15:20:51.415792+00');
INSERT INTO public.retention_policies VALUES ('6a59aa68-3f15-49a1-ab2f-38fcba0b117f', NULL, 'operational', 'remediation_plans', '5', '0', NULL, 'true', 'ISO 27001 A.5.33', 'Remediation evidence retained 5 years', '2026-04-29 15:20:51.415792+00');
INSERT INTO public.retention_policies VALUES ('e10ddf41-d4e0-47f6-b79c-1e43960b7cb5', NULL, 'personal_data', NULL, '0', '0', NULL, 'false', 'GDPR Art.17', 'Erasure on data subject request within 30 days', '2026-04-29 15:20:51.415792+00');
INSERT INTO public.retention_policies VALUES ('29748336-20a7-41a4-afcc-8021e570ce0b', NULL, 'personal_data', 'users', '0', '0', NULL, 'false', 'GDPR Art.17', 'User accounts anonymised on erasure request', '2026-04-29 15:20:51.415792+00');
INSERT INTO public.retention_policies VALUES ('97d781ee-c2a0-43aa-98b2-94938eeebb78', NULL, 'platform', NULL, '0', '30', NULL, 'true', 'Contractual', 'Soft deleted on tenant offboarding, purged after 30 days', '2026-04-29 15:20:51.415792+00');
INSERT INTO public.retention_policies VALUES ('ee217216-dcc5-48de-b7fa-eccabdfa47ab', NULL, 'session', NULL, '0', '90', NULL, 'true', 'GDPR Art.5(1)(e)', 'Conversation history auto-purged after 90 days', '2026-04-29 15:20:51.415792+00');
INSERT INTO public.retention_policies VALUES ('9661c041-a9de-4046-883d-8f01884e7524', NULL, 'compliance', 'confirmation_log', '7', '0', NULL, 'false', 'ISO 27001 A.5.33, GDPR Art.5(1)(d) accuracy principle', 'Confirmation audit trail — who confirmed what and when. Required to demonstrate competent human review of compliance posture.', '2026-05-02 07:58:56.295289+00');
INSERT INTO public.retention_policies VALUES ('334cec5f-cbc8-4e78-ae6b-c99eec00d570', NULL, 'operational', 'request_trace_log', '5', '0', NULL, 'true', 'ISO 27001 A.5.33, GDPR Art.5(1)(e)', 'Request traces retained 5 years for audit and performance analysis. Auto-purge permitted after retention period.', '2026-05-02 08:04:10.701454+00');
INSERT INTO public.retention_policies VALUES ('d19d9216-e1ae-4e36-9abb-a1c44208839d', NULL, 'platform', 'tenant_source_registry', '0', '30', NULL, 'true', 'Contractual', 'Source registrations soft-deleted on disconnection, purged 30 days after soft delete.', '2026-05-02 08:04:10.701454+00');

COMMIT;
